// per-letter colours of the weather icons
// alert icons: 'A' = state colour, other letters fixed (ICON_COLORS)
inline uint32_t icon_color(char letter, uint32_t main) {
  if (letter == 'O') return 0xFF8C28;
  if (letter == 'P') return 0x969696;
  if (letter == 'B') return 0x3C7D50;
  return main;
}
inline uint32_t weather_color(char letter) {
  switch (letter) {
    case 'S': return 0xF2C14E;
    case 'C': return 0xD6D6D6;
    case 'R': return 0x2AD4E0;
    case 'W': return 0xFFFFFF;
    case 'B': return 0xF2C14E;
    case 'F': return 0x6E6E6E;
    case 'M': return 0xE8DEAA;
    case 'T': return 0xD6D6D6;
    default: return C_FG;
  }
}

